876	static void RideRatingsCalculate(RideRating::UpdateState& state, Ride& ride)
877	{
878	    const auto& rrd = ride.getRideTypeDescriptor().RatingsData;
879	
880	    switch (rrd.Type)
881	    {
882	        case RatingsCalculationType::Normal:
883	            if (!ride.flags.has(RideFlag::tested))
884	                return;
885	            break;
886	        case RatingsCalculationType::FlatRide:
887	            ride.flags.set(RideFlag::tested, RideFlag::noRawStats);
888	            break;
889	        case RatingsCalculationType::Stall:
890	            ride.upkeepCost = RideComputeUpkeep(state, ride);
891	            ride.windowInvalidateFlags.set(RideInvalidateFlag::income);
892	            // Exit ratings
893	            return;
894	    }
895	
896	    ride.unreliabilityFactor = rrd.Unreliability;
897	    SetUnreliabilityFactor(ride);
898	
899	    const auto shelteredEighths = GetNumOfShelteredEighths(ride);
900	    ride.shelteredEighths = (rrd.RideShelter == kDynamicRideShelterRating) ? shelteredEighths.TotalShelteredEighths
901	                                                                           : rrd.RideShelter;
902	
903	    RideRating::Tuple ratings = rrd.BaseRatings;
904	    // Apply Modifiers
905	    for (const auto& modifier : rrd.Modifiers)
906	    {
907	        switch (modifier.type)
908	        {
909	            case RatingsModifierType::BonusLength:
910	                RideRatingsApplyBonusLength(ratings, ride, modifier);
911	                break;
912	            case RatingsModifierType::BonusSynchronisation:
913	                RideRatingsApplyBonusSynchronisation(ratings, ride, modifier);
914	                break;
915	            case RatingsModifierType::BonusTrainLength:
916	                RideRatingsApplyBonusTrainLength(ratings, ride, modifier);
917	                break;
918	            case RatingsModifierType::BonusMaxSpeed:
919	                RideRatingsApplyBonusMaxSpeed(ratings, ride, modifier);
920	                break;
921	            case RatingsModifierType::BonusAverageSpeed:
922	                RideRatingsApplyBonusAverageSpeed(ratings, ride, modifier);
923	                break;
924	            case RatingsModifierType::BonusDuration:
925	                RideRatingsApplyBonusDuration(ratings, ride, modifier);
926	                break;
927	            case RatingsModifierType::BonusGForces:
928	                RideRatingsApplyBonusGForces(ratings, ride, modifier);
929	                break;
930	            case RatingsModifierType::BonusTurns:
931	                RideRatingsApplyBonusTurns(ratings, ride, modifier);
932	                break;
933	            case RatingsModifierType::BonusDrops:
934	                RideRatingsApplyBonusDrops(ratings, ride, modifier);
935	                break;
936	            case RatingsModifierType::BonusSheltered:
937	                RideRatingsApplyBonusSheltered(ratings, ride, modifier);
938	                break;
939	            case RatingsModifierType::BonusProximity:
940	                RideRatingsApplyBonusProximity(ratings, ride, state, modifier);
941	                break;
942	            case RatingsModifierType::BonusScenery:
943	                RideRatingsApplyBonusScenery(ratings, ride, modifier);
944	                break;
945	            case RatingsModifierType::BonusRotations:
946	                RideRatingsApplyBonusRotations(ratings, ride, modifier);
947	                break;
948	            case RatingsModifierType::BonusOperationOption:
