1027	                break;
1028	        }
1029	
1030	        // Requirements that may be ignored if the ride has inversions
1031	        if (ride.numInversions == 0 || !rrd.RelaxRequirementsIfInversions)
1032	        {
1033	            switch (modifier.type)
