1035	                case RatingsModifierType::RequirementDropHeight:
1036	                    RideRatingsApplyRequirementDropHeight(ratings, ride, modifier);
1037	                    break;
1038	                case RatingsModifierType::RequirementNumDrops:
1039	                    RideRatingsApplyRequirementNumDrops(ratings, ride, modifier);
1040	                    break;
1041	                case RatingsModifierType::RequirementNegativeGs:
1042	                    RideRatingsApplyRequirementNegativeGs(ratings, ride, modifier);
1043	                    break;
1044	                default:
1045	                    break;
1046	            }
1047	        }
1048	    }
1049	    // Universl ratings adjustments
1050	    RideRatingsApplyIntensityPenalty(ratings);
1051	    RideRatingsApplyAdjustments(ride, ratings);
1052	    if (ride.ratings != ratings)
1053	    {
1054	        ride.ratings = ratings;
1055	        ride.windowInvalidateFlags.set(RideInvalidateFlag::ratings);
1056	    }
1057	
1058	    ride.upkeepCost = RideComputeUpkeep(state, ride);
1059	    ride.windowInvalidateFlags.set(RideInvalidateFlag::income);
1060	
1061	#ifdef ORIGINAL_RATINGS
1062	    if (!ride.ratings.isNull())
1063	    {
1064	        // Address underflows allowed by original RCT2 code
1065	        ride.ratings.excitement = std::max<uint16_t>(0, ride.ratings.excitement);
1066	        ride.ratings.intensity = std::max<uint16_t>(0, ride.ratings.intensity);
1067	        ride.ratings.nausea = std::max<uint16_t>(0, ride.ratings.nausea);
1068	    }
1069	#endif
1070	
1071	#ifdef ENABLE_SCRIPTING
1072	    // Only call the 'ride.ratings.calculate' API hook if testing of the ride is complete
1073	    if (ride.flags.has(RideFlag::tested))
1074	    {
1075	        auto& hookEngine = GetContext()->GetScriptEngine().GetHookEngine();
1076	        if (hookEngine.HasSubscriptions(HookType::rideRatingsCalculate))
1077	        {
1078	            auto ctx = GetContext()->GetScriptEngine().GetContext();
1079	            auto originalRatings = ride.ratings;
1080	
1081	            // Create event args object
1082	            JSValue obj = JS_NewObject(ctx);
1083	            JS_SetPropertyStr(ctx, obj, "rideId", JS_NewInt32(ctx, ride.id.ToUnderlying()));
1084	            JS_SetPropertyStr(ctx, obj, "excitement", JS_NewInt32(ctx, originalRatings.excitement));
1085	            JS_SetPropertyStr(ctx, obj, "intensity", JS_NewInt32(ctx, originalRatings.intensity));
1086	            JS_SetPropertyStr(ctx, obj, "nausea", JS_NewInt32(ctx, originalRatings.nausea));
1087	
1088	            // Call the subscriptions
1089	            hookEngine.Call(HookType::rideRatingsCalculate, obj, true, true);
1090	
1091	            auto scriptExcitement = AsOrDefault(ctx, obj, "excitement", static_cast<int32_t>(originalRatings.excitement));
1092	            auto scriptIntensity = AsOrDefault(ctx, obj, "intensity", static_cast<int32_t>(originalRatings.intensity));
1093	            auto scriptNausea = AsOrDefault(ctx, obj, "nausea", static_cast<int32_t>(originalRatings.nausea));
