1104	static void RideRatingsCalculateValue(Ride& ride)
1105	{
1106	    struct Row
1107	    {
1108	        int32_t months, multiplier, divisor, summand;
1109	    };
1110	    static constexpr auto kAgeTable = std::to_array<Row>({
1111	        { 5, 1, 1, 30 },      // +30
1112	        { 13, 1, 1, 10 },     // +10
1113	        { 40, 1, 1, 0 },      // 1x
1114	        { 64, 3, 4, 0 },      // 0.75x
1115	        { 88, 9, 16, 0 },     // 0.56x
1116	        { 104, 27, 64, 0 },   // 0.42x
1117	        { 120, 81, 256, 0 },  // 0.32x
1118	        { 128, 81, 512, 0 },  // 0.16x
1119	        { 200, 81, 1024, 0 }, // 0.08x
1120	        { 200, 9, 16, 0 },    // 0.56x "easter egg"
1121	    });
1122	
1123	    if (!RideHasRatings(ride))
1124	    {
1125	        return;
1126	    }
1127	
1128	    // Start with the base ratings, multiplied by the ride type specific weights for excitement, intensity and nausea.
1129	    const auto& ratingsMultipliers = ride.getRideTypeDescriptor().RatingsMultipliers;
1130	    money64 value = (((ride.ratings.excitement * ratingsMultipliers.excitement) * 32) >> 15)
1131	        + (((ride.ratings.intensity * ratingsMultipliers.intensity) * 32) >> 15)
1132	        + (((ride.ratings.nausea * ratingsMultipliers.nausea) * 32) >> 15);
1133	
1134	    int32_t monthsOld = 0;
1135	    if (!getGameState().cheats.disableRideValueAging)
1136	    {
1137	        monthsOld = ride.getAge();
1138	    }
1139	
1140	    Row lastRow = kAgeTable[kAgeTable.size() - 1];
1141	
1142	    // Ride is older than oldest age in the table?
1143	    if (monthsOld >= lastRow.months)
1144	    {
1145	        value = (value * lastRow.multiplier) / lastRow.divisor + lastRow.summand;
1146	    }
1147	    else
1148	    {
1149	        // Find the first hit in the table that matches this ride's age
1150	        for (const Row& curr : kAgeTable)
1151	        {
1152	            if (monthsOld < curr.months)
1153	            {
1154	                value = (value * curr.multiplier) / curr.divisor + curr.summand;
1155	                break;
1156	            }
1157	        }
1158	    }
1159	
1160	    // Other ride of same type penalty
1161	    const auto& gameState = getGameState();
1162	    const auto& rideManager = RideManager(gameState);
1163	    auto rideType = ride.type;
1164	    auto otherRidesOfSameType = std::count_if(rideManager.begin(), rideManager.end(), [rideType](const Ride& r) {
1165	        return r.status == RideStatus::open && r.type == rideType;
1166	    });
1167	    if (otherRidesOfSameType > 1)
1168	        value -= value / 4;
1169	
1170	    ride.value = std::max(0.00_GBP, value);
1171	}
