1173	/**
1174	 * I think this function computes ride upkeep? Though it is weird that the
1175	 *  rct2: Sub65E621
1176	 * inputs
1177	 * - edi: ride ptr
1178	 */
1179	static money64 RideComputeUpkeep(RideRating::UpdateState& state, const Ride& ride)
1180	{
1181	    // data stored at 0x0057E3A8, incrementing 18 bytes at a time
1182	    auto upkeep = ride.getRideTypeDescriptor().UpkeepCosts.BaseCost;
1183	
1184	    auto trackCost = ride.getRideTypeDescriptor().UpkeepCosts.CostPerTrackPiece;
1185	    upkeep += trackCost * ride.numPoweredLifts;
1186	
1187	    uint32_t totalLength = ToHumanReadableRideLength(ride.getTotalLength());
1188	
1189	    // The data originally here was 20's and 0's. The 20's all represented
1190	    // rides that had tracks. The 0's were fixed rides like crooked house or
1191	    // dodgems.
1192	    // Data source is 0x0097E3AC
1193	    totalLength *= ride.getRideTypeDescriptor().UpkeepCosts.TrackLengthMultiplier;
1194	    upkeep += static_cast<uint16_t>(totalLength >> 10);
1195	
1196	    if (ride.flags.has(RideFlag::onRidePhoto))
1197	    {
1198	        // The original code read from a table starting at 0x0097E3AE and
1199	        // incrementing by 0x12 bytes between values. However, all of these
1200	        // values were 40. I have replaced the table lookup with the constant
1201	        // 40 in this case.
1202	        upkeep += 40;
1203	    }
1204	
1205	    // Add maintenance cost for reverser track pieces
1206	    upkeep += 10 * state.AmountOfReversers;
1207	
1208	    // Add maintenance cost for brake track pieces
1209	    upkeep += 20 * state.AmountOfBrakes;
1210	
1211	    // Add maintenance cost for booster track pieces
1212	    upkeep += 80 * state.amountOfBoosters;
1213	
1214	    // these seem to be adhoc adjustments to a ride's upkeep/cost, times
1215	    // various variables set on the ride itself.
1216	
1217	    // https://gist.github.com/kevinburke/e19b803cd2769d96c540
1218	    upkeep += ride.getRideTypeDescriptor().UpkeepCosts.CostPerTrain * ride.numTrains;
1219	    upkeep += ride.getRideTypeDescriptor().UpkeepCosts.CostPerCar * ride.numCarsPerTrain;
1220	
1221	    // slight upkeep boosts for some rides - 5 for mini railway, 10 for log
1222	    // flume/rapids, 10 for roller coaster, 28 for giga coaster
1223	    upkeep += ride.getRideTypeDescriptor().UpkeepCosts.CostPerStation * ride.numStations;
1224	
1225	    if (ride.mode == RideMode::reverseInclineLaunchedShuttle)
1226	    {
1227	        upkeep += 30;
1228	    }
1229	    else if (ride.mode == RideMode::poweredLaunchPassthrough)
1230	    {
1231	        upkeep += 160;
1232	    }
1233	    else if (ride.mode == RideMode::limPoweredLaunch)
1234	    {
1235	        upkeep += 320;
1236	    }
1237	    else if (ride.mode == RideMode::poweredLaunch || ride.mode == RideMode::poweredLaunchBlockSectioned)
1238	    {
1239	        upkeep += 220;
1240	    }
1241	
1242	    // multiply by 5/8
1243	    upkeep *= 10;
1244	    upkeep >>= 4;
1245	    return upkeep;
1246	}
