1248	/**
1249	 *
1250	 *  rct2: 0x0065E7FB
1251	 *
1252	 * inputs
1253	 * - bx: excitement
1254	 * - cx: intensity
1255	 * - bp: nausea
1256	 * - edi: ride ptr
1257	 */
1258	static void RideRatingsApplyAdjustments(const Ride& ride, RideRating::Tuple& ratings)
1259	{
1260	    const auto* rideEntry = GetRideEntryByIndex(ride.subtype);
1261	
1262	    if (rideEntry == nullptr)
1263	    {
1264	        return;
1265	    }
1266	
1267	    // Apply ride entry multipliers
1268	    RideRatingsAdd(
1269	        ratings, ((static_cast<int32_t>(ratings.excitement) * rideEntry->excitement_multiplier) >> 7),
1270	        ((static_cast<int32_t>(ratings.intensity) * rideEntry->intensity_multiplier) >> 7),
1271	        ((static_cast<int32_t>(ratings.nausea) * rideEntry->nausea_multiplier) >> 7));
1272	
1273	    // Apply total air time
1274	#ifdef ORIGINAL_RATINGS
1275	    if (ride.getRideTypeDescriptor().flags.has(RtdFlag::hasAirTime))
1276	    {
1277	        uint16_t totalAirTime = ride.totalAirTime;
1278	        if (rideEntry->flags.has(RideEntryFlag::limitAirTimeBonus))
1279	        {
1280	            if (totalAirTime >= 96)
1281	            {
1282	                totalAirTime -= 96;
1283	                ratings.excitement -= totalAirTime / 8;
1284	                ratings.nausea += totalAirTime / 16;
1285	            }
1286	        }
1287	        else
1288	        {
1289	            ratings.excitement += totalAirTime / 8;
1290	            ratings.nausea += totalAirTime / 16;
1291	        }
1292	    }
1293	#else
1294	    if (ride.getRideTypeDescriptor().flags.has(RtdFlag::hasAirTime))
1295	    {
1296	        int32_t excitementModifier;
1297	        int32_t totalAirTime = ride.totalAirTime;
1298	        if (rideEntry->flags.has(RideEntryFlag::limitAirTimeBonus))
1299	        {
1300	            totalAirTime = std::max(0, totalAirTime - 96);
1301	            excitementModifier = -1 * (std::min<uint16_t>(totalAirTime, 200) / 8);
1302	        }
1303	        else
1304	        {
1305	            excitementModifier = std::min<uint16_t>(totalAirTime, 200) / 8;
1306	        }
1307	        int32_t nauseaModifier = totalAirTime / 16;
1308	
1309	        RideRatingsAdd(ratings, excitementModifier, 0, nauseaModifier);
1310	    }
1311	#endif
1312	}
