1314	/**
1315	 * Lowers excitement, the higher the intensity.
1316	 *  rct2: 0x0065E7A3
1317	 */
1318	static void RideRatingsApplyIntensityPenalty(RideRating::Tuple& ratings)
1319	{
1320	    static constexpr RideRating_t intensityBounds[] = { 1000, 1100, 1200, 1320, 1450 };
1321	    RideRating_t excitement = ratings.excitement;
1322	    for (auto intensityBound : intensityBounds)
1323	    {
1324	        if (ratings.intensity >= intensityBound)
1325	        {
1326	            excitement -= excitement / 4;
1327	        }
1328	    }
1329	    ratings.excitement = excitement;
1330	}
