1413	/**
1414	 * Calculates how much of the track is sheltered in eighths.
1415	 *  rct2: 0x0065E72D
1416	 */
1417	static ShelteredEights GetNumOfShelteredEighths(const Ride& ride)
1418	{
1419	    int32_t totalLength = ride.getTotalLength();
1420	    int32_t shelteredLength = ride.shelteredLength;
1421	    int32_t lengthEighth = totalLength / 8;
1422	    int32_t lengthCounter = lengthEighth;
1423	    uint8_t numShelteredEighths = 0;
1424	    for (int32_t i = 0; i < 7; i++)
1425	    {
1426	        if (shelteredLength >= lengthCounter)
1427	        {
1428	            lengthCounter += lengthEighth;
1429	            numShelteredEighths++;
1430	        }
1431	    }
1432	
1433	    uint8_t trackShelteredEighths = numShelteredEighths;
1434	    const auto* rideType = GetRideEntryByIndex(ride.subtype);
1435	    if (rideType == nullptr)
1436	    {
1437	        return { 0, 0 };
1438	    }
1439	    if (rideType->flags.has(RideEntryFlag::isACoveredRide))
1440	        numShelteredEighths = 7;
1441	
1442	    return { trackShelteredEighths, numShelteredEighths };
1443	}
