1632	/**
1633	 *
1634	 *  rct2: 0x0065E1C2
1635	 */
1636	static RideRating::Tuple ride_ratings_get_sheltered_ratings(const Ride& ride)
1637	{
1638	    int32_t shelteredLengthShifted = (ride.shelteredLength) >> 16;
1639	
1640	    uint32_t shelteredLengthUpTo1000 = std::min(shelteredLengthShifted, 1000);
1641	    uint32_t shelteredLengthUpTo2000 = std::min(shelteredLengthShifted, 2000);
1642	
1643	    int32_t excitement = (shelteredLengthUpTo1000 * 9175) >> 16;
1644	    int32_t intensity = (shelteredLengthUpTo2000 * 0x2666) >> 16;
1645	    int32_t nausea = (shelteredLengthUpTo1000 * 0x4000) >> 16;
1646	
1647	    /*eax = (ride.var11C * 30340) >> 16;*/
1648	    /*nausea += eax;*/
1649	
1650	    if (ride.numShelteredSections & ShelteredSectionsBits::kBankingWhileSheltered)
1651	    {
1652	        excitement += 20;
1653	        nausea += 15;
1654	    }
1655	
1656	    if (ride.numShelteredSections & ShelteredSectionsBits::kRotatingWhileSheltered)
1657	    {
1658	        excitement += 20;
1659	        nausea += 15;
1660	    }
1661	
1662	    uint8_t lowerVal = ride.getNumShelteredSections();
1663	    lowerVal = std::min<uint8_t>(lowerVal, 11);
1664	    excitement += (lowerVal * 774516) >> 16;
1665	
1666	    RideRating::Tuple rating = { static_cast<RideRating_t>(excitement), static_cast<RideRating_t>(intensity),
1667	                                 static_cast<RideRating_t>(nausea) };
1668	    return rating;
1669	}
