1671	/**
1672	 *
1673	 *  rct2: 0x0065DCDC
1674	 */
1675	static RideRating::Tuple ride_ratings_get_gforce_ratings(const Ride& ride)
1676	{
1677	    RideRating::Tuple result = {
1678	        .excitement = 0,
1679	        .intensity = 0,
1680	        .nausea = 0,
1681	    };
1682	
1683	    // Apply maximum positive G force factor
1684	    result.excitement += (ride.maxPositiveVerticalG * 5242) >> 16;
1685	    result.intensity += (ride.maxPositiveVerticalG * 52428) >> 16;
1686	    result.nausea += (ride.maxPositiveVerticalG * 17039) >> 16;
1687	
1688	    // Apply maximum negative G force factor
1689	    fixed16_2dp gforce = ride.maxNegativeVerticalG;
1690	    result.excitement += (std::clamp<fixed16_2dp>(gforce, -RideRating::make(2, 50), RideRating::make(0, 00)) * -15728) >> 16;
1691	    result.intensity += ((gforce - RideRating::make(1, 00)) * -52428) >> 16;
1692	    result.nausea += ((gforce - RideRating::make(1, 00)) * -14563) >> 16;
1693	
1694	    // Apply lateral G force factor
1695	    result.excitement += (std::min<fixed16_2dp>(RideRating::make(1, 50), ride.maxLateralG) * 26214) >> 16;
1696	    result.intensity += ride.maxLateralG;
1697	    result.nausea += (ride.maxLateralG * 21845) >> 16;
1698	
1699	// Very high lateral G force penalty
1700	#ifdef ORIGINAL_RATINGS
1701	    if (ride.maxLateralG > MakeFixed16_2dp(2, 80))
1702	    {
1703	        result.intensity += RideRating::make(3, 75);
1704	        result.nausea += RideRating::make(2, 00);
1705	    }
1706	    if (ride.maxLateralG > MakeFixed16_2dp(3, 10))
1707	    {
1708	        result.excitement /= 2;
1709	        result.intensity += RideRating::make(8, 50);
1710	        result.nausea += RideRating::make(4, 00);
1711	    }
1712	#endif
1713	
1714	    return result;
1715	}
