1717	/**
1718	 *
1719	 *  rct2: 0x0065E139
1720	 */
1721	static RideRating::Tuple ride_ratings_get_drop_ratings(const Ride& ride)
1722	{
1723	    RideRating::Tuple result = {
1724	        /* .excitement = */ 0,
1725	        /* .intensity = */ 0,
1726	        /* .nausea = */ 0,
1727	    };
1728	
1729	    // Apply number of drops factor
1730	    int32_t drops = ride.numDrops;
1731	    result.excitement += (std::min(9, drops) * 728177) >> 16;
1732	    result.intensity += (drops * 928426) >> 16;
1733	    result.nausea += (drops * 655360) >> 16;
1734	
1735	    // Apply highest drop factor
1736	    RideRatingsAdd(
1737	        result, ((ride.highestDropHeight * 2) * 16000) >> 16, ((ride.highestDropHeight * 2) * 32000) >> 16,
1738	        ((ride.highestDropHeight * 2) * 10240) >> 16);
1739	
1740	    return result;
1741	}
