1743	/**
1744	 * Calculates a score based on the surrounding scenery.
1745	 *  rct2: 0x0065E557
1746	 */
1747	static int32_t ride_ratings_get_scenery_score(const Ride& ride)
1748	{
1749	    auto stationIndex = RideGetFirstValidStationStart(ride);
1750	    CoordsXY location;
1751	
1752	    if (stationIndex.IsNull())
1753	    {
1754	        return 0;
1755	    }
1756	
1757	    const auto& rtd = ride.getRideTypeDescriptor();
1758	    if (rtd.specialType == RtdSpecialType::maze)
1759	    {
1760	        location = ride.getStation().Entrance.ToCoordsXY();
1761	    }
1762	    else
1763	    {
1764	        location = ride.getStation(stationIndex).Start;
1765	    }
1766	
1767	    int32_t z = TileElementHeight(location);
1768	
1769	    // Check if station is underground, returns a fixed mediocre score since you can't have scenery underground
1770	    if (z > ride.getStation(stationIndex).GetBaseZ())
1771	    {
1772	        return 40;
1773	    }
1774	
1775	    // Count surrounding scenery items
1776	    int32_t numSceneryItems = 0;
1777	    auto tileLocation = TileCoordsXY(location);
1778	    auto& gameState = getGameState();
1779	    for (int32_t yy = std::max(tileLocation.y - 5, 0); yy <= std::min(tileLocation.y + 5, gameState.mapSize.y - 1); yy++)
1780	    {
1781	        for (int32_t xx = std::max(tileLocation.x - 5, 0); xx <= std::min(tileLocation.x + 5, gameState.mapSize.x - 1); xx++)
1782	        {
1783	            // Count scenery items on this tile
1784	            TileElement* tileElement = MapGetFirstElementAt(TileCoordsXY{ xx, yy });
1785	            if (tileElement == nullptr)
1786	                continue;
1787	            do
1788	            {
1789	                if (tileElement->isGhost())
1790	                    continue;
1791	
1792	                const auto type = tileElement->getType();
1793	                if (type == TileElementType::smallScenery || type == TileElementType::largeScenery)
1794	                    numSceneryItems++;
1795	            } while (!(tileElement++)->isLastForTile());
1796	        }
1797	    }
1798	
1799	    return std::min(numSceneryItems, 47) * 5;
1800	}
